import { FACTS } from '../data/site'

/**
 * Three facts in a dot-marked row. The dots are generated by CSS at `.6em`, so
 * they track the first line at any type size instead of sitting on a bullet.
 */
export function Facts() {
  return (
    <ul className="td-facts">
      {FACTS.map((fact) => (
        <li key={fact.strong}>
          <strong>{fact.strong}</strong>
          {fact.rest}
        </li>
      ))}
    </ul>
  )
}
